'use strict';
window.CoalitionScenario = (() => {
  const D=window.PoliticsData,M=window.PoliticsModel,L=window.LegislationModel;
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const signed=n=>(n>0?'+':'')+Number(n.toFixed(1));
  const dot=p=>`<i class="dot" style="background:${p.color}"></i>`;
  const indicators=[
    {color:'#55aa88',up:'Расширяются общественные услуги и защита от социальных рисков.',down:'Больше роли у адресной помощи и личных сбережений.',upCost:'Нужны устойчивые источники финансирования и дополнительные специалисты.',downCost:'Доступность услуг сильнее зависит от доходов.'},
    {color:'#20a6b0',up:'Проще запускать проекты, инвестировать и менять производство.',down:'Сильнее контроль отраслей и защита занятости.',upCost:'Выше рыночные риски; необходима защита людей при переменах.',downCost:'Сложнее адаптировать предприятия; слабее конкуренция.'},
    {color:'#9b7cc6',up:'Больше участия граждан и возможностей публичного контроля.',down:'Больше полномочий у централизованных институтов.',upCost:'Согласование решений требует времени и работающих процедур.',downCost:'Слабее независимый контроль и прямое влияние граждан.'},
    {color:'#6698d0',up:'Расширяются возможности обмена, торговли, поездок и образования.',down:'Больший приоритет у собственных правил и внутренних связей.',upCost:'Результат сильнее зависит от международных соглашений и внешних условий.',downCost:'Часть рынков, технологий и программ становится менее доступной.'},
    {color:'#bd9652',up:'Расширяются технологические возможности производства и образования.',down:'Технологические проекты получают меньше возможностей для развития.',upCost:'Подготовка кадров, оборудование и инфраструктура требуют ресурсов.',downCost:'Сложнее обновлять производство и удерживать специалистов.'},
    {color:'#a07783',up:'Растут возможности оборонных отраслей и военной инфраструктуры.',down:'Ресурсы смещаются в пользу гражданской экономики и дипломатии.',upCost:'Меньше бюджетного пространства для гражданских программ.',downCost:'Военные возможности растут медленнее; важнее внешние договорённости.'}
  ];
  const statusNames={passed:'Принят',rejected:'Отклонён',notScheduled:'Отложен',pending:'Впереди'};
  const sourceNames={program:'Основа: программа',initiative:'Основа: инициатива',modeled:'Сценарная адаптация'};
  function mount(container,getResult){
    let c=getResult(),members=(M.coalitions(c.totals,c.enabled)[0]?.members||[]).map(k=>c.enabled[k]),year=2031,implementation=.7,discipline=.7,filter='all',author='all',simulation;
    const openBills=new Set();
    container.innerHTML=`<section class="box scenario-box"><div class="scenario-heading"><div><span class="scenario-eyebrow">ВАША ДУМА → ЗАКОНЫ → РОССИЯ</span><h3>Что изменится к 2031 году</h3><p class="hint">Соберите коалицию, договоритесь о поправках и проследите путь от голосования до результата.</p></div><span class="year-seal" id="scenario-year-seal">2031</span></div><div class="coalition-builder"><h4>Кто входит в вашу коалицию</h4><div id="scenario-coalition" class="coalition-choices"></div><p class="coalition-status" id="scenario-status" aria-live="polite"></p></div><div class="scenario-controls"><label class="year-control"><span>Год <b id="scenario-year">2031</b></span><input id="scenario-timeline" type="range" min="2026" max="2031" step="1" value="2031" aria-label="Год сценария"><small><span>2026</span><span>2027</span><span>2028</span><span>2029</span><span>2030</span><span>2031</span></small></label><label><span>Способность исполнять <b id="scenario-implementation">70%</b></span><input id="scenario-effort" type="range" min="0" max="100" step="5" value="70" aria-label="Способность исполнять программу"><small><span>Много препятствий</span><span>Все ресурсы доступны</span></small></label><label><span>Дисциплина коалиции <b id="scenario-discipline">70%</b></span><input id="scenario-whip" type="range" min="0" max="100" step="5" value="70" aria-label="Дисциплина коалиции"><small><span>Каждый за себя</span><span>Согласованный курс</span></small></label></div><p class="scenario-caption">Сценарная модель: индексы от условной базы 2026 = 50. Меняются вследствие принятых законов. Голосования рассчитаны по позициям партий; ресурс — условные единицы.</p><div class="legislation-summary" id="legislation-summary" aria-live="polite"></div><div class="law-timeline" id="law-timeline" aria-label="История работы парламента"></div><div class="annual-report" id="annual-report"></div><div class="scenario-indicators" id="scenario-indicators">${indicators.map((x,i)=>`<article class="indicator" style="--indicator-color:${x.color}"><div class="indicator-title"><h4>${L.labels[i]}</h4><span class="indicator-value" id="indicator-value-${i}">50</span></div><div class="indicator-scale"><i id="indicator-fill-${i}" style="width:50%"></i><em title="2026: 50"></em></div><span class="indicator-delta" id="indicator-delta-${i}"></span><p class="indicator-benefit" id="indicator-benefit-${i}"></p><p class="indicator-cost" id="indicator-cost-${i}"></p><div class="indicator-laws" id="indicator-laws-${i}"></div></article>`).join('')}</div><div class="compromises"><h4>Коалиционные компромиссы</h4><div id="scenario-compromises"></div></div><div class="laws-heading"><div><h4>Законы вашего созыва</h4><p class="hint">27 инициатив · по три от каждой партии. Откройте проект, чтобы увидеть голос каждой фракции.</p></div><div class="law-filters"><label>Статус<select id="law-status"><option value="all">Все проекты</option><option value="passed">Принятые</option><option value="rejected">Отклонённые</option><option value="notScheduled">Отложенные</option><option value="pending">Ещё не внесены</option></select></label><label>Автор<select id="law-author"><option value="all">Все партии</option>${D.parties.map(p=>`<option value="${p.id}">${p.short}</option>`).join('')}</select></label></div></div><div class="law-list" id="law-list"></div><details class="scenario-method"><summary>Как работают голосования, повестка и эффекты</summary><p>Каждому проекту нужны 226 голосов. Партии голосуют по близости своих оценок к проекту; неизвестная позиция даёт воздержание. Членство в коалиции повышает поддержку согласованных поправок, но сохраняет голоса против при сильных разногласиях. Повестка ставит выше проекты коалиции, затем учитывает приоритет, ожидание и поддержку.</p><p>Способность исполнять определяет число рассматриваемых проектов, доступный ресурс и скорость результата. Поправки могут смягчать меры вместе с их ценой и эффектом. Доходные инициативы пополняют ресурс; проекты без финансирования ждут. Противоположные правила госзаказа на чипы заменяют друг друга, а эффект отменённого курса постепенно затухает.</p><p>От принятых мер реализуется 45% эффекта в первый год, 75% во второй, полный эффект с третьего; затем применяется коэффициент исполнения. Шесть индексов ограничены диапазоном 10–90. Это направление изменений, а не измеренные показатели экономики. Фракционные доли, годы, эффекты и цены — правила модели; официальные источники подтверждают только указанные программные направления и инициативы.</p></details></section>`;
    const find=id=>container.querySelector('#'+id);
    find('scenario-coalition').onclick=e=>{const b=e.target.closest('[data-coalition-party]');if(!b)return;const p=+b.dataset.coalitionParty;members=members.includes(p)?members.filter(i=>i!==p):[...members,p];update();};
    find('scenario-timeline').oninput=e=>{year=+e.target.value;update(false);};
    find('scenario-effort').oninput=e=>{implementation=+e.target.value/100;update(false);};
    find('scenario-whip').oninput=e=>{discipline=+e.target.value/100;update(false);};
    find('law-timeline').onclick=e=>{const b=e.target.closest('[data-year]');if(b){year=+b.dataset.year;update(false);}};
    find('law-status').onchange=e=>{filter=e.target.value;renderLaws();};
    find('law-author').onchange=e=>{author=e.target.value;renderLaws();};
    find('law-list').addEventListener('toggle',e=>{const id=e.target.dataset.bill;if(id){e.target.open?openBills.add(id):openBills.delete(id);}},true);
    container.onclick=e=>{const a=e.target.closest('[data-law-link]');if(!a)return;e.preventDefault();filter='all';author='all';find('law-status').value=filter;find('law-author').value=author;openBills.add(a.dataset.lawLink);renderLaws();find('law-'+a.dataset.lawLink)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});};
    function lawLink(b){return `<a href="#law-${b.id}" data-law-link="${b.id}">${escape(b.title)}</a>`;}
    function targetText(id,value){const q=D.questions.find(q=>q.id===id),n=value/q.d;return Math.abs(n)<.2?'Между вариантами':n<0?q.a:q.b;}
    function renderLaws(){
      const shown=simulation.bills.filter(b=>(filter==='all'||b.status===filter)&&(author==='all'||b.sponsors.includes(author)));
      find('law-list').innerHTML=shown.length?shown.map(b=>{
        const voted=['passed','rejected'].includes(b.status),authors=b.sponsors.map(id=>D.parties.find(p=>p.id===id)),strength=Math.round(b.amendmentScale*100);
        return `<details class="law-card" data-bill="${b.id}" id="law-${b.id}" ${openBills.has(b.id)?'open':''}><summary><span class="law-author-dots">${authors.map(dot).join('')}</span><span class="law-title">${escape(b.title)}<small>${authors.map(p=>p.short).join(' + ')} · ${b.year||b.proposedYear}${b.amended?' · с поправками':''}${b.repealedYear?' · заменён в '+b.repealedYear:''}</small></span><span class="law-outcome"><span class="law-badge ${b.status}">${statusNames[b.status]}</span>${voted?`<small>${b.yesSeats} за / 226</small>`:''}</span></summary><div class="law-body"><p>${escape(b.description)}</p><p class="law-reason">${escape(b.reason)}</p>${b.repealedBy?`<p>Новый курс: ${lawLink(simulation.bills.find(x=>x.id===b.repealedBy))}.</p>`:''}<div class="bill-vote-bar" aria-label="${b.yesSeats} за, ${b.noSeats} против, ${b.abstainSeats} воздержались"><i class="vote-yes" style="width:${b.yesSeats/450*100}%"></i><i class="vote-no" style="width:${b.noSeats/450*100}%"></i><i class="vote-abstain" style="width:${b.abstainSeats/450*100}%"></i><em title="Порог: 226 голосов"></em></div><div class="vote-totals"><span><i class="dot vote-yes"></i>${b.yesSeats} за</span><span><i class="dot vote-no"></i>${b.noSeats} против</span><span><i class="dot vote-abstain"></i>${b.abstainSeats} воздержались</span></div>${!voted?'<p class="hint vote-preview">Ожидаемая поддержка при текущем составе и поправках; голосование ещё не состоялось.</p>':''}<div class="vote-table-wrap"><table class="vote-table"><thead><tr><th>Фракция</th><th>За</th><th>Против</th><th>Возд.</th></tr></thead><tbody>${b.votes.filter(v=>v.seats).map(v=>`<tr><th><details><summary>${dot(D.parties[v.index])}${v.name}${v.inCoalition?'<span class="coalition-mark" title="В коалиции">●</span>':''}</summary><p>${escape(v.reason)}</p></details></th><td>${v.yes}</td><td>${v.no}</td><td>${v.abstain}</td></tr>`).join('')}</tbody></table></div><details class="bill-amendments"><summary>${b.amended?'Что изменили поправки · масштаб '+strength+'%':'Какие решения заложены в проект'}</summary>${Object.entries(b.proposalTargets).map(([id,value])=>`<div><b>${escape(D.questions.find(q=>q.id===id).title)}</b><p>${escape(targetText(id,value))}</p>${Math.abs(value-b.amendedTargets[id])>.04?`<small>Коалиция смягчила эту позицию: ${Math.round(Math.abs(b.amendedTargets[id])*100)}% от края шкалы вместо ${Math.round(Math.abs(value)*100)}%.</small>`:''}</div>`).join('')}</details><div class="bill-effects"><span>Ресурс: ${b.budgetCost<0?'пополняет на '+Math.abs(b.budgetCost):'требуется '+b.budgetCost}</span>${Object.entries(b.realizedEffects).filter(([,n])=>Math.abs(n)>=.05).map(([k,n])=>`<span>${L.labels[L.keys.indexOf(k)]}: ${signed(n)}</span>`).join('')}${b.status==='passed'&&!Object.values(b.realizedEffects).some(n=>Math.abs(n)>=.05)?'<span>Эффект пока не реализован</span>':''}</div><details class="bill-source"><summary>${sourceNames[b.source?.kind]||'Источник направления'}</summary>${b.source?`<a href="${escape(b.source.url)}" target="_blank" rel="noopener noreferrer">${escape(b.source.title)}${b.source.year?' · '+b.source.year:''}</a><p>${escape(b.source.note)}</p>`:'<p>Редакционный сценарий.</p>'}</details>${b.attempts.length>1?`<details class="bill-source"><summary>История рассмотрения</summary>${b.attempts.map(a=>`<p><b>${a.year}</b> · ${escape(a.reason)}</p>`).join('')}</details>`:''}</div></details>`;
      }).join(''):'<p class="law-empty">В выбранной категории пока нет проектов. Измените год, фильтр или состав коалиции.</p>';
    }
    function update(renderChoices=true){
      c=getResult();members=members.filter(p=>c.enabled.includes(p)&&c.totals[c.enabled.indexOf(p)]>0);
      simulation=L.simulate({totals:c.totals,enabled:c.enabled,coalition:members,throughYear:year,implementation,discipline});
      if(renderChoices)find('scenario-coalition').innerHTML=c.enabled.map((p,k)=>`<button data-coalition-party="${p}" aria-pressed="${members.includes(p)}" ${!c.totals[k]?'disabled':''} style="--party-color:${D.parties[p].color}">${dot(D.parties[p])}${D.parties[p].short}<b>${c.totals[k]}</b></button>`).join('');
      const status=find('scenario-status');status.textContent=`${simulation.coalitionSeats} из 450 мест · ${simulation.coalitionMajority?'большинство собрано':members.length?'до большинства ещё '+(226-simulation.coalitionSeats)+'; нужны голоса других фракций':'выберите фракции для совместной программы'}`;status.classList.toggle('enough',simulation.coalitionMajority);
      find('scenario-year').textContent=year;find('scenario-year-seal').textContent=year;find('scenario-timeline').value=year;find('scenario-implementation').textContent=Math.round(implementation*100)+'%';find('scenario-discipline').textContent=Math.round(discipline*100)+'%';
      const summary=simulation.summary;
      find('legislation-summary').innerHTML=[['Принято',summary.passed,'passed'],['Отклонено',summary.rejected,'rejected'],['Ждут повестки',summary.notScheduled,'deferred'],['Ещё впереди',summary.pending,'upcoming']].map(([name,n,cls])=>`<div class="${cls}"><b>${n}</b><span>${name}</span></div>`).join('');
      const full=year===2031?simulation:L.simulate({totals:c.totals,enabled:c.enabled,coalition:members,throughYear:2031,implementation,discipline});
      find('law-timeline').innerHTML=`<button data-year="2026" aria-pressed="${year===2026}"><b>2026</b><span>Точка отсчёта</span></button>`+full.timeline.map(t=>`<button data-year="${t.year}" aria-pressed="${year===t.year}"><b>${t.year}</b><span>${t.passed} принято</span><small>${t.rejected} отклонено</small></button>`).join('');
      const annual=simulation.timeline.at(-1);
      find('annual-report').innerHTML=annual?`<span><b>${year}:</b> рассмотрено ${annual.considered} из ${annual.agendaCapacity} возможных проектов</span><span>Ресурс: ${Number(annual.budget.opening.toFixed(1))} + ${Number(annual.budget.raised.toFixed(1))} поступлений − ${Number(annual.budget.spent.toFixed(1))} расходов = <b>${Number(annual.budget.remaining.toFixed(1))}</b></span>`:'<span>2026: начало созыва. Законы ещё не внесены, все индексы в точке отсчёта.</span>';
      simulation.indicators.forEach((value,i)=>{const item=indicators[i],zero=Math.abs(value.delta)<.05,positive=value.delta>0;find(`indicator-value-${i}`).textContent=Number(value.value.toFixed(1));find(`indicator-fill-${i}`).style.width=value.value+'%';find(`indicator-delta-${i}`).textContent=zero?'Без изменений к 2026 году':signed(value.delta)+' к 2026 году';find(`indicator-benefit-${i}`).textContent=zero?'Принятые меры пока не изменили это направление.':positive?item.up:item.down;find(`indicator-cost-${i}`).textContent=zero?'':'Издержки: '+(positive?item.upCost:item.downCost);const contributing=simulation.adopted.filter(b=>Math.abs(b.realizedEffects[value.id])>=.05).sort((a,b)=>Math.abs(b.realizedEffects[value.id])-Math.abs(a.realizedEffects[value.id]));find(`indicator-laws-${i}`).innerHTML=contributing.slice(0,2).map(b=>`<span>${lawLink(b)} <b>${signed(b.realizedEffects[value.id])}</b></span>`).join('');});
      const compromises=simulation.bills.filter(b=>b.amended&&b.sponsorInCoalition&&b.proposedYear<=year).sort((a,b)=>a.amendmentScale-b.amendmentScale).slice(0,3);
      find('scenario-compromises').innerHTML=compromises.length?compromises.map(b=>`<article class="compromise"><b>${lawLink(b)}</b><p>Масштаб мер: ${Math.round(b.amendmentScale*100)}% исходного проекта · ${b.yesSeats} голосов за · ${statusNames[b.status].toLowerCase()}.</p></article>`).join(''):`<p class="hint">${year===2026?'Перейдите к следующему году, чтобы увидеть первые согласования.':!members.length?'Выберите участников коалиции, чтобы согласовать их проекты.':!discipline?'Увеличьте дисциплину, чтобы фракции согласовывали поправки.':'Проекты выбранных участников пока не потребовали смягчения.'}</p>`;
      renderLaws();
    }
    update();return {update};
  }
  return {mount};
})();
